KG42.register("source_edge_archive-99981deccc13a82bcd70bb41",{"id":"12-p2p_microgrid_trading::v141-c-R007::E::v141-c-R007-E001","paper":"12-p2p_microgrid_trading","rule_id":"v141-c-R007","rule_ref":"12-p2p_microgrid_trading::v141-c-R007","record":{"edge_id":"v141-c-R007-E001","source":"bidding.demand","target":"bidding.supply","type":"links","constraint_ids":["v141-c-R007-C001"],"evidence_ids":["v141-b-g01-ev-14","v141-b-g01-ev-15"]},"evidence_class":"S","provenance_gate":"direct_C_edge_with_constraint_and_source_excerpt","scientific_acceptance":false,"accepted_constraint_ids":["v141-c-R007-C001"],"held_constraint_ids":[],"semantic_review_status":"supported","source":"COMP-b9841ac99d9d29b8","target":"COMP-b3f649e90c1f17b9","source_occurrence_id":"12-p2p_microgrid_trading::v141-c-R007::V::bidding.demand","target_occurrence_id":"12-p2p_microgrid_trading::v141-c-R007::V::bidding.supply","source_unit_id":"12-p2p_microgrid_trading::v141-a-M02::bidding.demand","target_unit_id":"12-p2p_microgrid_trading::v141-a-M02::bidding.supply","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"bidding","context_text":"Elecbay alternative seller-initiated order placement for half-hour energy requirements. | Elecbay publishing and bidding period. | Illustrative Elecbay order-modification or cancellation rule, applied to supply orders. | Information contained in Elecbay supply orders. | Modification or cancellation of Elecbay supply orders after gate closure. | Peer-initiated placement, cancellation and modification of Elecbay supply orders.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-ev-13","v141-b-g01-ev-14","v141-b-g01-ev-15","v141-b-g01-ev-21","v141-b-g01-ev-23","v141-b-g01-ev-24"]},"active":true,"source_signature":"3bd95abc04ce94588f4edd96b796690ffa583b00731694b8e639185a91c05fb3","relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"source_science":{"mechanism_id":"v141-a-M02","source_definition":"Peers may list the energy required over half an hour for purchase and place demand orders. Scope: Elecbay requested-energy listings and purchase orders for half-hourly energy exchanges. Condition: During the publishing and bidding time period. Each demand order contains the energy-exchange time period, amount, price and seller and buyer details. Identities and energy-supply reliability ratings are examples of those details. Scope: Information contained in demand orders placed on Elecbay. Peers may place, cancel or modify demand orders only before gate closure, which is one hour before the energy-exchange period in this paper. Scope: Placement, cancellation and modification of Elecbay demand orders by peers. Only DSOs have permission to modify or cancel demand orders after gate closure under this condition. Scope: Modification or cancellation of Elecbay demand orders after gate closure. Condition: A network constraint violation has been identified. Demand orders placed later, closer to gate closure, have a higher possibility of cancellation. Scope: Illustrative Elecbay order-cancellation policy, not an assertion that this policy was adopted. Condition: If the example last on first off principle is applied.","target_definition":"Buyers' demand submissions provide the listed half-hour energy requirements that sellers browse when placing supply orders. Scope: Elecbay alternative seller-initiated order placement for half-hour energy requirements. Condition: When sellers browse items listed by energy buyers and place orders against those requirements. Peers may list their surplus energy over half an hour for sale and place supply orders. Scope: Elecbay publishing and bidding period. Condition: During the publishing and bidding time period. Each supply order contains the energy-exchange time period, energy quantity, energy price, and seller and buyer details, including identities and energy-supply reliability ratings. Scope: Information contained in Elecbay supply orders. Peers may place, cancel or modify supply orders only before gate closure. Scope: Peer-initiated placement, cancellation and modification of Elecbay supply orders. Condition: Before gate closure, which is one hour before the energy exchange time period in this paper. DSOs alone have permission to modify or cancel supply orders in this condition. Scope: Modification or cancellation of Elecbay supply orders after gate closure. Condition: After gate closure, once a network constraint violation has been identified. Supply orders placed later, closer to gate closure, have a higher possibility of cancellation. Scope: Illustrative Elecbay order-modification or cancellation rule, applied to supply orders. Condition: If the example last on first off principle is used.","constraints":[{"constraint_id":"v141-c-R007-C001","kind":"procedural","role":"core","statement":"Buyers' demand submissions provide the listed half-hour energy requirements that sellers browse when placing supply orders. Scope: Elecbay alternative seller-initiated order placement for half-hour energy requirements. Condition: When sellers browse items listed by energy buyers and place orders against those requirements.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand","bidding.supply"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-ev-14","v141-b-g01-ev-15"]}],"evidence":[{"evidence_id":"v141-b-g01-ev-14","location":{"location_id":"src-c1934be9b4-p04-c1r2__v141-a-M02-bidding","page":4,"printed_page":null,"section":"3. Platform for Peer-to-Peer energy trading","anchor_text":"Order Pre-payment Fig. 2. Interactions of key players d the information including the time period fo","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Each order contains the information including the time period for the energy exchange, the amount of energy to be exchanged, the price of the energy to be exchanged and the details about the seller and buyer, e.g. the identities, the ratings of energy supply reliability, etc."},{"evidence_id":"v141-b-g01-ev-15","location":{"location_id":"src-c1934be9b4-p04-c1r2__v141-a-M02-bidding","page":4,"printed_page":null,"section":"3. Platform for Peer-to-Peer energy trading","anchor_text":"Order Pre-payment Fig. 2. Interactions of key players d the information including the time period fo","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Alternatively, energy sellers can also browse the items listed by energy buyers, i.e. the required energy over half an hour, and then place orders."}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"bidding","context_text":"Elecbay alternative seller-initiated order placement for half-hour energy requirements. | Elecbay publishing and bidding period. | Illustrative Elecbay order-modification or cancellation rule, applied to supply orders. | Information contained in Elecbay supply orders. | Modification or cancellation of Elecbay supply orders after gate closure. | Peer-initiated placement, cancellation and modification of Elecbay supply orders.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-ev-13","v141-b-g01-ev-14","v141-b-g01-ev-15","v141-b-g01-ev-21","v141-b-g01-ev-23","v141-b-g01-ev-24"]},"source_record":{"edge_id":"v141-c-R007-E001","source":"bidding.demand","target":"bidding.supply","type":"links","constraint_ids":["v141-c-R007-C001"],"evidence_ids":["v141-b-g01-ev-14","v141-b-g01-ev-15"]},"paper_scope_note":"Buyer order placement and seller order placement are alternative processes; payment to the platform and the platform's distribution of bills are not the same data object; temporal order only preserves the source fact."}});
